import socket,selectors,time,errno,ipaddress
def execute(endpoints,stagger=.05,timeout=.5):
    if not isinstance(endpoints,list) or not 1<=len(endpoints)<=8:raise ValueError('1..8 endpoints required')
    if isinstance(stagger,bool) or isinstance(timeout,bool) or not isinstance(stagger,(int,float)) or not isinstance(timeout,(int,float)) or not 0<stagger<=.1 or not stagger<timeout<=1:raise ValueError('invalid timing')
    for family,host,port in endpoints:
        if not isinstance(host,str):raise ValueError('numeric IP text required')
        address=ipaddress.ip_address(host)
        if not address.is_loopback or family not in [socket.AF_INET,socket.AF_INET6] or address.version!=(4 if family==socket.AF_INET else 6) or type(port) is not int or not 1<=port<=65535:raise ValueError('numeric loopback endpoint required')
    selector=selectors.DefaultSelector();pending={};next_index=0;next_launch=time.monotonic();deadline=next_launch+timeout;last_error=errno.ECONNREFUSED
    def finish(connection,index):
        connection.setblocking(True);connection.settimeout(1);return connection,index
    try:
        while time.monotonic()<deadline:
            now=time.monotonic()
            if next_index<len(endpoints) and (now>=next_launch or not pending):
                index=next_index;next_index+=1;family,host,port=endpoints[index]
                try:connection=socket.socket(family,socket.SOCK_STREAM)
                except OSError as error:last_error=error.errno;next_launch=now;continue
                try:
                    connection.setblocking(False);code=connection.connect_ex((host,port))
                    if code==0:return finish(connection,index)
                    if code in (errno.EINPROGRESS,errno.EWOULDBLOCK,errno.EALREADY,errno.EINTR):
                        selector.register(connection,selectors.EVENT_WRITE);pending[connection]=index;next_launch=now+stagger
                    else:connection.close();last_error=code;next_launch=now;continue
                except Exception:connection.close();raise
            if not pending and next_index==len(endpoints):raise OSError(last_error,'all connection attempts failed')
            now=time.monotonic();wait=max(0,deadline-now)
            if next_index<len(endpoints):wait=min(wait,max(0,next_launch-now))
            for key,mask in selector.select(wait):
                connection=key.fileobj;index=pending.pop(connection);selector.unregister(connection)
                code=connection.getsockopt(socket.SOL_SOCKET,socket.SO_ERROR)
                if code==0:return finish(connection,index)
                last_error=code;connection.close()
        raise TimeoutError('connection deadline exceeded')
    finally:
        for connection in pending:connection.close()
        selector.close()
